//! Genuine pointer validation calls preserve actual App paint and interaction.
use super::*;
struct Fixture(std::path::PathBuf);
impl Drop for Fixture{fn drop(&mut self){let _=std::fs::remove_file(&self.0);}}
fn node(app:&App,id:&str)->usize{let mut pending=vec![0];while let Some(n)=pending.pop(){if app.document.dom_attr(n,"id").is_some_and(|v|v.raw_units().is_none()&&v.as_str()==id){return n;}pending.extend(app.document.nodes[n].children.iter().rev().copied());}panic!("connected node {id}")}
#[test]
fn control_type_actual_app_pointer_paint_focus_editor_and_links(){
 let file=Fixture(std::env::temp_dir().join(format!("chezcat-app-control-type-metadata-{}.html",std::process::id())));
 std::fs::write(&file.0,r#"<!doctype html><style>body{margin:0;background:white}output{display:block;position:absolute;left:20px;top:20px;width:120px;height:32px;background:#114455}#go{position:absolute;left:220px;top:20px;width:160px;height:32px}#neighbor{position:absolute;left:220px;top:100px;width:180px;height:30px}#stable{position:absolute;left:420px;top:100px}</style><body><form id=owner><input id=owned_input value=seed style='position:absolute;left:20px;top:250px;width:100px'><button id=owned_button type=button style='position:absolute;left:140px;top:250px'>Owned</button><select id=owned_select style='position:absolute;left:250px;top:250px'><option>One</option></select><textarea id=owned_textarea style='position:absolute;left:350px;top:250px'>Seed</textarea><output id=output for=seed name=result>ready</output></form><input id=neighbor value=neighbor><a id=stable href=#destination>Go</a><button id=go type=button>Validate output</button><div id=destination></div><script>var output=document.getElementById('output'),owner=output.form,labels=output.labels,tokens=output.htmlFor,invalid=0,round=0;output.value='current';output.addEventListener('invalid',function(){invalid++;});document.addEventListener('invalid',function(){invalid++;},true);document.getElementById('go').onclick=function(e){if(!e.isTrusted)throw 'native pointer';var s=document.getElementById('owned_select'),t=document.getElementById('owned_textarea'),a=Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype,'type').get,b=Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype,'type').get;if(a.call(s)!=='select-one'||s.type!=='select-one'||b.call(t)!=='textarea'||t.type!=='textarea'||s.form!==owner||t.form!==owner)throw 'canonical type';var inert=new Document().createElementNS('http://www.w3.org/1999/xhtml','select');inert.setAttribute('multiple','false');if(inert.type!=='select-multiple')throw 'actual presence';inert.removeAttribute('multiple');if(inert.type!=='select-one')throw 'live presence';var focus=document.activeElement,watch=new MutationObserver(function(){});watch.observe(output,{attributes:true,childList:true,subtree:true,characterData:true});if(output.willValidate!==false||output.validationMessage!==''||output.checkValidity()!==true||output.reportValidity()!==true||invalid!==0||document.activeElement!==focus)throw 'native noncandidate validation';if(watch.takeRecords().length||output.value!=='current'||output.defaultValue!=='ready'||output.form!==owner||output.labels!==labels||output.htmlFor!==tokens||tokens.value!=='seed')throw 'validation changed native state';watch.disconnect();document.title='Control type '+round;round++;};</script>"#).unwrap();
 let mut app=App::new();app.resize(640,480);app.set_javascript_enabled(true);app.open(&file.0);assert!(!app.failed&&!app.is_loading(),"{}",app.status);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0);let initial=app.draw();assert_eq!(initial.pixels[(app.content_top()+40)as usize*initial.width+110],0x114455);
 let go=node(&app,"go");let neighbor=node(&app,"neighbor");let stable=node(&app,"stable");app.forms.script_set_value(neighbor,"edited neighbor").unwrap();{let e=&mut app.forms.controls.get_mut(&neighbor).unwrap().value;e.cursor=5;e.anchor=2;e.offset=1;}let raw=app.raw.clone();let location=app.location.clone();let epoch=app.script_epoch;let scroll=app.scroll;
 for round in 0..3{let rect=app.page.controls.iter().find(|r|r.node==go).unwrap();let(x,y)=(rect.x+rect.width/2,app.content_top()+rect.y+rect.height/2-app.scroll);app.pointer_down(x,y,false);app.pointer_up(x,y);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());assert_eq!(app.document.title,format!("Control type {round}"));let painted=app.draw();assert_eq!(painted.pixels[(app.content_top()+40)as usize*painted.width+110],0x114455);let e=&app.forms.controls[&neighbor].value;assert_eq!((e.text(),e.cursor,e.anchor,e.offset),("edited neighbor".into(),5,2,1));assert_eq!(app.page.link_node_at(430,110),Some(stable));assert_eq!(app.raw,raw);assert_eq!(app.location,location);assert_eq!(app.script_epoch,epoch);assert_eq!(app.scroll,scroll);}
}
